window.HOEREN_TESTS[9] = {"id":"einkaufen-und-geschaefte","name":"Einkaufen und Geschäfte","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden, herzlich willkommen im Supermarkt Frischeparadies. Heute haben wir besondere Angebote: Erdbeeren ein Kilo nur 2,99 Euro, Milch im Drei-Liter-Pack 4,50 Euro. Außerdem ist heute Sonderaktion bei Wein — jede dritte Flasche kostenlos. Nicht 50 Prozent auf alles, nur jede dritte Flasche Wein gratis. Die Aktion gilt nur bis 20 Uhr. Genießen Sie Ihren Einkauf! Viel Spaß beim Einkaufen!","gender":"f","q":"Wie ist das Angebot bei Wein?","opts":["Jede zweite Flasche kostenlos.","Alle Flaschen 50% billiger.","Jede dritte Flasche kostenlos."],"correct":2},{"transcript":"Hallo Schatz, hier ist Mama. Kannst du beim Einkaufen heute noch Brot und Milch mitbringen? Brot vom Bäcker, nicht vom Supermarkt — das schmeckt besser. Egal woher die Milch kommt, aber Brot bitte vom Bäcker. Auch noch Tomaten, wenn die schön aussehen. Bis später! Danke! Beeil dich bitte!","gender":"f","q":"Woher soll das Brot kommen?","opts":["Vom Supermarkt.","Egal woher.","Vom Bäcker."],"correct":2},{"transcript":"Sehr geehrte Kunden, die Kasse 5 ist leider kaputt — bitte gehen Sie zur Kasse 3 oder 7. Wir entschuldigen uns für die Wartezeit. Wir bitten Kunden mit großem Einkauf, die Kasse 3 zu nutzen, weil die schneller ist. Kunden mit wenigen Artikeln können auch die Express-Kasse 7 nutzen. Danke!","gender":"m","q":"Welche Kasse ist für Kunden mit großem Einkauf?","opts":["Kasse 3.","Kasse 5.","Kasse 7."],"correct":0},{"transcript":"Hallo Frau Wagner, hier ist Schuhgeschäft Lauffit. Die Schuhe, die Sie bestellt haben, sind angekommen — aber in der falschen Größe. Statt 38 ist die Größe 39 da. Sie haben richtig bestellt, Frau Wagner, das war unser Fehler. Wir bestellen jetzt nochmal die richtige Größe. Es dauert noch eine Woche. Tut uns leid für die Wartezeit.","gender":"f","q":"Was ist das Problem?","opts":["Die Schuhe sind nicht angekommen.","Die Schuhe sind in falscher Größe.","Frau Wagner hat falsche Größe bestellt."],"correct":1},{"transcript":"Achtung an alle Kunden im Einkaufszentrum. Heute schließen wir schon um 18 Uhr statt um 22 Uhr, weil eine private Veranstaltung stattfindet. Letzter Einlass ist um 17 Uhr 30. Morgen sind wir wieder zu normalen Zeiten geöffnet. Vielen Dank für Ihr Verständnis und einen schönen Einkauf. Bitte kommen Sie morgen wieder!","gender":"f","q":"Wann schließt das Einkaufszentrum heute?","opts":["Um 17 Uhr 30.","Um 18 Uhr.","Um 22 Uhr."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kauft was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Anna","gender":"f","text":"Hallo Markus! Das Gartenfest am Samstag braucht einen Plan. Ich habe einen Zettel geschrieben."},{"speaker":"Markus","gender":"m","text":"Leg ihn auf den Tisch. Wir teilen den Einkauf und die Arbeit in der Küche."},{"speaker":"Anna","gender":"f","text":"Ich kaufe Blumen auf dem Markt. Gelbe und weiße stelle ich dann in die Vasen."},{"speaker":"Markus","gender":"m","text":"Blumen machen den Garten freundlich. Backt noch jemand selbst Kuchen für den Kaffee?"},{"speaker":"Anna","gender":"f","text":"Nein. Selbstgebackene Kuchen bringt niemand mit. Dafür fehlt uns einfach die Zeit."},{"speaker":"Markus","gender":"m","text":"Ich kaufe Wein und Sekt im Laden an der Ecke."},{"speaker":"Anna","gender":"f","text":"Wir trinken Sekt und auch Wein zum Essen. Das reicht gut für alle Gäste."},{"speaker":"Markus","gender":"m","text":"Lisa macht das Buffet mit Käse und Brot. Sie schneidet alles früh am Morgen."},{"speaker":"Anna","gender":"f","text":"Käse und Brot mag bei uns jeder. Tom kümmert sich um den Ton im Garten."},{"speaker":"Markus","gender":"m","text":"Tom organisiert die Musik mit einer kleinen Anlage. Er bringt zwei Lautsprecher mit."},{"speaker":"Anna","gender":"f","text":"Die Musik soll eher leise bleiben. Macht jemand bei dem Fest auch Fotos von den Gästen?"},{"speaker":"Markus","gender":"m","text":"Fotos machen wir nicht. Das überlassen wir ganz den Gästen."},{"speaker":"Anna","gender":"f","text":"Was stellen wir danach als Dessert auf den Tisch?"},{"speaker":"Markus","gender":"m","text":"Sara bringt Eis zum Dessert. Vanille und Schokolade stehen schon auf ihrer Liste."},{"speaker":"Anna","gender":"f","text":"Dann hänge ich den Zettel an den Kühlschrank. Wir sehen uns Samstag um zwei."}],"options":[{"letter":"a","text":"kauft Blumen"},{"letter":"b","text":"macht das Buffet (Käse, Brot)"},{"letter":"c","text":"bringt selbstgebackene Kuchen"},{"letter":"d","text":"putzt die Wohnung"},{"letter":"e","text":"macht Fotos"},{"letter":"f","text":"organisiert die Musik"},{"letter":"g","text":"bringt ein Geschenk mit"},{"letter":"h","text":"kauft Wein und Sekt"},{"letter":"i","text":"bringt Eis zum Dessert"}],"items":[{"person":"Anna","correct":"a"},{"person":"Markus","correct":"h"},{"person":"Lisa","correct":"b"},{"person":"Tom","correct":"f"},{"person":"Sara","correct":"i"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Verkäuferin","gender":"f","text":"Was suchen Sie?"},{"speaker":"Kunde","gender":"m","text":"Eine Hose. Größe 32. Für die Arbeit, nichts Sportliches."},{"speaker":"Verkäuferin","gender":"f","text":"Welche Farbe? Wir haben Blau, Schwarz und Beige."},{"speaker":"Kunde","gender":"m","text":"Schwarz ist mir zu klassisch. Beige? Hmm, die könnte gut sein, oder?"},{"speaker":"Verkäuferin","gender":"f","text":"Hier ist die beige Hose in Größe 32. Möchten Sie sie anprobieren?"},{"speaker":"Kunde","gender":"m","text":"Perfekt, die nehme ich in Größe 32. Danke schön!"}],"q":"Welche Hose nimmt der Kunde?","opts":["Die blaue.","Die schwarze.","Die beige."],"correct":2},{"lines":[{"speaker":"Bäcker","gender":"m","text":"Was darf es sein?"},{"speaker":"Kundin","gender":"f","text":"Ein Vollkornbrot, bitte. Und zwei Croissants."},{"speaker":"Bäcker","gender":"m","text":"Tut mir leid, Croissants sind aus. Aber wir haben Brötchen — Mohn, Sesam oder Käse."},{"speaker":"Kundin","gender":"f","text":"Dann zwei Sesambrötchen statt der Croissants."},{"speaker":"Bäcker","gender":"m","text":"Sehr gut. Das macht 3 Euro 20, bitte."},{"speaker":"Kundin","gender":"f","text":"Hier bitte! Und Mohnbrötchen nehme ich nächstes Mal. Tschüss!"}],"q":"Was kauft die Kundin?","opts":["Vollkornbrot und zwei Croissants.","Vollkornbrot und Mohnbrötchen.","Vollkornbrot und zwei Sesambrötchen."],"correct":2},{"lines":[{"speaker":"Kassiererin","gender":"f","text":"Das macht 47 Euro 50."},{"speaker":"Kunde","gender":"m","text":"Kann ich mit Karte zahlen?"},{"speaker":"Kassiererin","gender":"f","text":"Ja, oder mit dem Handy. Bar geht ab heute leider nicht mehr, nur Karte oder Handy."},{"speaker":"Kunde","gender":"m","text":"Mit Karte, dann. Geht das hier vorne?"},{"speaker":"Kassiererin","gender":"f","text":"Ja, hier vorne bitte. Stecken oder kontaktlos?"},{"speaker":"Kunde","gender":"m","text":"Kontaktlos mit dem Handy, so modern! Danke, tschüss!"}],"q":"Wie zahlt der Kunde?","opts":["Mit dem Handy.","Mit Karte.","Bar."],"correct":0},{"lines":[{"speaker":"Kundin","gender":"f","text":"Ich möchte diese Schuhe umtauschen — sie passen nicht."},{"speaker":"Verkäuferin","gender":"f","text":"Haben Sie den Bon?"},{"speaker":"Kundin","gender":"f","text":"Ja, hier."},{"speaker":"Verkäuferin","gender":"f","text":"Sie können das Geld zurück haben oder ein neues Paar in Ihrer Größe wählen."},{"speaker":"Kundin","gender":"f","text":"Geld zurück, bitte. Mir gefällt das Modell nicht so gut."},{"speaker":"Verkäuferin","gender":"f","text":"Schade! Hier ist Ihr Geld. Bis zum nächsten Mal!"}],"q":"Was wählt die Kundin?","opts":["Sie tauscht in ihrer Größe.","Sie nimmt das Geld zurück.","Sie behält die Schuhe."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Haben Sie das Buch ‚Die Welt von gestern‘?"},{"speaker":"Verkäuferin","gender":"f","text":"Moment, ich schaue. Ja, einmal vorrätig. 18 Euro."},{"speaker":"Kunde","gender":"m","text":"Im Internet finde ich es für 14 Euro."},{"speaker":"Verkäuferin","gender":"f","text":"Wir können leider den Preis nicht senken. Aber wir geben ein Lesezeichen kostenlos dazu."},{"speaker":"Kunde","gender":"m","text":"Okay, ich nehme das Buch hier. 18 Euro, stimmt so."}],"q":"Wo kauft der Kunde das Buch?","opts":["Im Buchladen.","Im Internet.","Er kauft es nicht."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Schmidt, einer Verkäuferin in einem Modegeschäft. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Schmidt, Sie arbeiten seit 18 Jahren im Modegeschäft Stil. Wie sind Sie hierhergekommen?"},{"speaker":"Schmidt","gender":"f","text":"Ich wollte eigentlich Modedesignerin werden. Aber das Studium war zu teuer für meine Familie. Ich habe stattdessen eine Lehre als Einzelhandelskauffrau gemacht. Jetzt bin ich seit 18 Jahren hier, und ich liebe meinen Beruf."},{"speaker":"Reporter","gender":"m","text":"Was lieben Sie an diesem Beruf?"},{"speaker":"Schmidt","gender":"f","text":"Der Kontakt zu den Kunden. Jeder ist anders. Manche wissen genau, was sie suchen. Andere brauchen Hilfe, um den richtigen Stil zu finden. Das ist wie Detektivarbeit, eine schöne Herausforderung."},{"speaker":"Reporter","gender":"m","text":"Gibt es auch schwierige Kunden?"},{"speaker":"Schmidt","gender":"f","text":"Manchmal, vor allem in der Sale-Zeit, wenn alle in Eile sind. Aber meistens sind die Leute freundlich. Ein Lächeln und Geduld helfen fast immer."},{"speaker":"Reporter","gender":"m","text":"Wie ist die Konkurrenz mit dem Online-Handel?"},{"speaker":"Schmidt","gender":"f","text":"Schwer, viele kaufen online, vor allem die Jüngeren. Aber wir haben einen Vorteil: man kann hier anprobieren und sieht die Farben in echt. Online ist die Farbe oft anders."},{"speaker":"Reporter","gender":"m","text":"Kaufen Sie selbst online?"},{"speaker":"Schmidt","gender":"f","text":"Nie Kleidung! Bücher und Elektronik ja, aber Kleidung möchte ich anziehen können. Auch ich brauche das Geschäft, nicht nur ein Foto im Internet."}],"items":[{"q":"Sie arbeitet sehr gern mit Kunden.","correct":"ja"},{"q":"Frau Schmidt ist gelernte Modedesignerin.","correct":"nein"},{"q":"Schwierige Kunden gibt es vor allem in der Sale-Zeit.","correct":"ja"},{"q":"Sie kauft ihre Kleidung online.","correct":"nein"},{"q":"Im Internet sind die Farben oft anders als in echt.","correct":"ja"}]}]};
